1	// Package overlay draws a box over already-rendered, ANSI-styled lines
2	// without cutting an escape sequence or shifting a wide rune.
3	package overlay
4	
5	import (
6		"strings"
7	
8		"github.com/charmbracelet/x/ansi"
9	
10		"github.com/anthnel/devdesk/internal/ui/theme"
11	)
12	
13	// sgrReset closes every SGR attribute in effect.
14	const sgrReset = "\x1b[0m"
15	
16	// Compose draws box over base, the top-left corner of the box landing at
17	// column x and row y. Rows of base that the box does not touch are returned
18	// as they are; base is never modified. Every row the box touches is rewritten
19	// to exactly width cells. A row on which the box cannot be spliced (it is
20	// wider than the room right of x) falls back to the box cut to the room right
21	// of x and spliced at x, so one failing row never spoils the others.
22	//
23	// Lines are single-row: a newline or a tab in base or box counts for no width
24	// (ansi.StringWidth) and is not supported.
25	//
26	// Nothing is drawn, and base is returned as is, when the box is empty, x is
27	// negative, or width is not positive. Rows of the box that fall above or
28	// below base are dropped.
29	func Compose(base, box []string, x, y, width int) []string {
30		if len(box) == 0 || x < 0 || width <= 0 || len(base) == 0 {
31			return base
32		}
33		out := make([]string, len(base))
34		copy(out, base)
35		for i, boxLine := range box {
36			row := y + i
37			if row < 0 || row >= len(out) {
38				continue
39			}
40			if boxLine == "" {
41				continue
42			}
43			spliced, ok := Splice(out[row], boxLine, x, width)
44			if !ok {
45				spliced = spliceCut(out[row], boxLine, x, width)
46			}
47			out[row] = spliced
48		}
49		return out
50	}
51	
52	// spliceCut is the per-row fallback of Compose: the box is cut to the room
53	// left of x and spliced at x, so the row keeps its left part. A row with no
54	// room at all is only fitted to width.
55	func spliceCut(line, box string, x, width int) string {
56		if x >= width {
57			return fit(line, width)
58		}
59		cut := ansi.Truncate(box, width-x, "")
60		out, ok := Splice(line, cut, x, width)
61		if !ok {
62			return fit(line, width)
63		}
64		return out
65	}
66	
67	// Splice replaces the cells of line from column x onward with box, and returns
68	// a line of exactly width cells. The base style active at the cut is restored
69	// after the box, and a wide rune cut in two is replaced by one space. It
70	// reports false, returning box cut to width, when box does not fit between x
71	// and width. Like Compose, it does not support newlines or tabs.
72	func Splice(line, box string, x, width int) (string, bool) {
73		bw := ansi.StringWidth(box)
74		if x < 0 || width <= 0 || x+bw > width {
75			return fit(box, width), false
76		}
77		line = fit(line, width)
78		if bw == 0 {
79			return line, true
80		}
81	
82		left := ansi.Truncate(line, x, "")
83		leftPad := bgSpaces(x - ansi.StringWidth(left))
84	
85		end := x + bw
86		right := ansi.TruncateLeft(line, end, "")
87		// A wide rune straddling the cut may be kept whole by TruncateLeft: drop
88		// one more cell until the right part fits, and let a space stand in.
89		for cut := end; ansi.StringWidth(right) > width-end; {
90			cut++
91			right = ansi.TruncateLeft(line, cut, "")
92		}
93		rightPad := width - end - ansi.StringWidth(right)
94	
95		var b strings.Builder
96		b.WriteString(left)
97		b.WriteString(sgrReset)
98		b.WriteString(leftPad)
99		b.WriteString(box)
100		b.WriteString(sgrReset)
101		if active := activeSGR(line, end); active != "" {
102			// The compensation cell keeps the style the base had at the cut.
103			b.WriteString(active)
104			b.WriteString(strings.Repeat(" ", rightPad))
105		} else {
106			b.WriteString(bgSpaces(rightPad))
107		}
108		b.WriteString(right)
109		return b.String(), true
110	}
111	
112	// fit cuts s to width cells and pads it with spaces when it is shorter.
113	func fit(s string, width int) string {
114		if width <= 0 {
115			return ""
116		}
117		s = ansi.Truncate(s, width, "")
118		if w := ansi.StringWidth(s); w < width {
119			s += sgrReset + bgSpaces(width-w)
120		}
121		return s
122	}
123	
124	// bgSpaces returns n spaces painted with the app background, so that a cell the
125	// overlay invents never shows the terminal's own background (Rule 115).
126	func bgSpaces(n int) string {
127		if n <= 0 {
128			return ""
129		}
130		return theme.Bg(strings.Repeat(" ", n))
131	}
132	
133	// activeSGR returns the SGR sequence in effect at column col of line. It only
134	// serves the compensation cell of a wide rune cut in two, which takes the
135	// base style at the cut; the right part itself gets its styling replayed by
136	// ansi.TruncateLeft. It is empty when nothing is active, and the last
137	// sequence since the latest reset wins.
138	func activeSGR(line string, col int) string {
139		var (
140			active string
141			pos    int
142			state  byte
143			rest   = line
144		)
145		for len(rest) > 0 && pos < col {
146			seq, width, n, newState := ansi.DecodeSequence(rest, state, nil)
147			state = newState
148			if width == 0 && isSGR(seq) {
149				active = style(seq)
