1	package cmdsuggest
2	
3	import (
4		"strings"
5	
6		"github.com/charmbracelet/lipgloss"
7		"github.com/charmbracelet/x/ansi"
8	
9		"github.com/anthnel/devdesk/internal/ui/theme"
10	)
11	
12	// Palette geometry, in cells and rows.
13	const (
14		// paletteChrome is the rows around the list: title, input, separator, rule.
15		paletteChrome = 4
16		// reducedHeight is title, input and rule, with no list.
17		reducedHeight = 3
18		// narrowWidth is the width below which the frame takes the whole line.
19		narrowWidth = 54
20		// maxPaletteWidth caps the frame on wide terminals.
21		maxPaletteWidth = 80
22		// sideMargin is the cells left free on each side of a framed palette.
23		sideMargin = 2
24	)
25	
26	// Rect is where the palette sits on screen, in cells and rows. Rows is the
27	// number of suggestion rows; Height is the whole frame.
28	type Rect struct{ X, Y, Width, Height, Rows int }
29	
30	// PaletteInput is everything RenderPalette needs.
31	type PaletteInput struct {
32		Title string // "Go to" or "Contexts"
33		Input string // the input line, already rendered by the caller
34		List  Input  // rows, cursor, notice; Width and Visible are set from Rect
35	}
36	
37	// PaletteRows returns the number of suggestion rows for v free lines: a
38	// constant of the geometry, independent of the number of matches.
39	func PaletteRows(v int) int {
40		return max(min(MaxVisibleRows, v-paletteChrome), 0)
41	}
42	
43	// Geometry places the palette for a width x height terminal whose header
44	// block is headerLines high and whose view footer is footerLines high. It
45	// never returns a negative field.
46	func Geometry(width, height, headerLines, footerLines int) Rect {
47		width, height = max(width, 0), max(height, 0)
48		headerLines, footerLines = max(headerLines, 0), max(footerLines, 0)
49	
50		rows := PaletteRows(height - headerLines - footerLines)
51		h := reducedHeight
52		if rows > 0 {
53			h = rows + paletteChrome
54		}
55		w := width
56		if width >= narrowWidth {
57			w = min(width-2*sideMargin, maxPaletteWidth)
58		}
59		y := headerLines
60		if y+h > height {
61			// Pull up onto the blank line under the header; the rest is clipped.
62			y = max(headerLines-1, 0)
63		}
64		return Rect{X: (width - w) / 2, Y: y, Width: w, Height: h, Rows: rows}
65	}
66	
67	func titleLook() look {
68		return look{name: "palette title", fg: theme.ColorText, bg: theme.ColorBackground, bold: true}
69	}
70	
71	func inputLook() look {
72		return look{name: "palette input", fg: theme.ColorText, bg: theme.ColorBackground}
73	}
74	
75	// BorderPalette lists the non-text pairs of the frame (border and prompt
76	// glyph), checked at 3:1 rather than 4.5:1.
77	func BorderPalette() []Pair {
78		return []Pair{
79			{Name: "palette border", Fg: theme.ColorPaletteBorder, Bg: theme.ColorBackground},
80			{Name: "palette prompt glyph", Fg: theme.ColorPaletteBorder, Bg: theme.ColorBackground},
81		}
82	}
83	
84	// RenderPalette returns r.Height lines of exactly r.Width cells, each with an
85	// explicit background: title border, input, then (when r.Rows > 0) a
86	// separator and the rows, and the bottom rule carrying the status.
87	func RenderPalette(p PaletteInput, r Rect) []string {
88		if r.Width < minRenderWidth {
89			return blankLines(r)
90		}
91		inner := r.Width - 2
92		border := lipgloss.NewStyle().Foreground(theme.ColorPaletteBorder).Background(theme.ColorBackground)
93	
94		lines := []string{titleLine(p.Title, inner, border), inputRow(p.Input, inner, border)}
95		if r.Rows > 0 {
96			lines = append(lines, border.Render("├"+strings.Repeat("─", inner)+"┤"))
97		}
98		list := p.List
99		list.Width, list.Visible = r.Width, r.Rows
100		lines = append(lines, renderWith(list, theme.ColorPaletteBorder)...)
101		return lines
102	}
103	
104	// blankLines is the palette on a terminal too narrow for a frame.
105	func blankLines(r Rect) []string {
106		lines := make([]string, r.Height)
107		for i := range lines {
108			lines[i] = theme.EmptyLineBg(max(r.Width, 0))
109		}
110		return lines
111	}
112	
113	// titleLine builds ┌─ Title ───┐ from separately styled segments.
114	func titleLine(title string, inner int, border lipgloss.Style) string {
115		title = ansi.Truncate(title, max(inner-3, 0), ellipsis)
116		dashes := max(inner-2-lipgloss.Width(title)-1, 0)
117		return border.Render("┌─ ") + titleLook().style().Render(title) +
118			border.Render(" "+strings.Repeat("─", dashes)+"┐")
119	}
120	
121	// inputRow frames the caller's rendered input with a one-cell margin and
122	// pads it with background up to the border.
123	func inputRow(input string, inner int, border lipgloss.Style) string {
124		side := border.Render("│")
125		room := max(inner-margin, 0)
126		if lipgloss.Width(input) > room {
127			input = ansi.Truncate(input, room, "")
128		}
129		pad := inputLook().style().Render(strings.Repeat(" ", margin))
130		fill := inputLook().style().Render(strings.Repeat(" ", max(room-lipgloss.Width(input), 0)))
131		return side + pad + input + fill + side
132	}
